-- world-14 ("Windows II & PowerShell: Blue Screen District") mission
-- content, generated from docs/12-world-story-bible.md. The mysterious
-- investigator (later revealed as the World 15 handoff target of Cipher's
-- trail) left PowerShell artifacts across several endpoints, but an
-- automated cleanup task is erasing them. Luna carries the Windows domain
-- into PowerShell: objects, pipelines, log hunts, Defender/Sysmon
-- correlation, ACLs and remote management. Cipher never gets spoken
-- dialogue here -- only planted textual clues discovered through evidence.
-- Mission 1 is cross-world-gated on world-13's boss mission.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-14a', 'world-14', 'blue-screen-district', '14A - Blue Screen District', 'PowerShell artifacts are scattered across several endpoints, and an automated cleanup task is erasing them while the Guardians work. Preserve the evidence, then read what it''s trying to say.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-14a-1', 'campaign-14a', 'foundations', 'Foundations', 'Objects, pipelines and precise log queries -- the vocabulary PowerShell actually speaks.', 1),
  ('operation-14a-2', 'campaign-14a', 'investigation', 'Investigation', 'Defender, Sysmon, ACLs and remoting -- recover the execution chain before the cleanup task finishes its work.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-w14-01', 'world-14', 'campaign-14a', 'operation-14a-1', 'blue-screen-district', 'Blue Screen District', 'PowerShell artifacts are scattered across several endpoints -- and an automated cleanup is erasing them while the Guardians investigate.', 'intro', ARRAY['luna', 'byte'], '{"requiredMissionIds":["mission-w13-06"]}'::jsonb, null, '{"type":"none"}'::jsonb, '{"xp":60,"credits":10}'::jsonb, false, 1),
  ('mission-w14-02', 'world-14', 'campaign-14a', 'operation-14a-1', 'objects-not-text', 'Objects, Not Text', 'Command-line tools return text. PowerShell returns objects, and that changes what you can ask.', 'beginner', ARRAY['luna'], '{"requiredMissionIds":["mission-w14-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"ps-pipeline-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 2),
  ('mission-w14-03', 'world-14', 'campaign-14a', 'operation-14a-1', 'the-log-before-it-vanishes', 'The Log Before It Vanishes', 'The evidence is still in the event log, for now. Query it precisely, before it isn''t.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-w14-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"ps-log-hunt-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 3),
  ('mission-w14-04', 'world-14', 'campaign-14a', 'operation-14a-2', 'blinded-on-purpose', 'Blinded on Purpose', 'Defender logged an exclusion nobody approved. Sysmon logged what happened right after.', 'beginner', ARRAY['luna'], '{"requiredMissionIds":["mission-w14-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"ps-defender-sysmon-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 4),
  ('mission-w14-05', 'world-14', 'campaign-14a', 'operation-14a-2', 'who-can-touch-this', 'Who Can Touch This', 'Check who can actually touch this evidence, and how to reach the other endpoints without tripping the same cleanup tool.', 'beginner', ARRAY['luna'], '{"requiredMissionIds":["mission-w14-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"ps-acl-remoting-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 5),
  ('mission-w14-06', 'world-14', 'campaign-14a', 'operation-14a-2', 'vanishing-evidence', 'Vanishing Evidence', 'Recover the full execution chain before the next cleanup cycle erases what''s left of it.', 'boss', ARRAY['luna', 'byte'], '{"requiredMissionIds":["mission-w14-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"vanishing-evidence-boss-sim"}'::jsonb, '{"xp":300,"credits":60,"badgeIds":["vanishing-evidence"],"skillXp":{"windows":50}}'::jsonb, true, 6);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w14-01', 1, 'luna', 'The PowerShell history you found wasn''t incidental. Whoever ran those commands left traces on multiple endpoints, and something is actively deleting them now.'),
  ('mission-w14-01', 2, 'byte', 'A scheduled cleanup task is wiping PowerShell logs and temp artifacts on a rolling basis. We''re racing it, not just investigating after the fact.'),
  ('mission-w14-01', 3, 'luna', 'This is where Windows stops being static configuration and starts being live investigation. PowerShell doesn''t just run commands -- it passes structured objects between them. That changes how you search.'),
  ('mission-w14-01', 4, 'byte', 'Whoever got here first is being careful. Comments in scripts, oddly specific variable names -- if that''s someone trying to talk to us, it''s not through a chat window.'),
  ('mission-w14-02', 1, 'luna', 'Command-line tools hand you text and expect you to parse it yourself. PowerShell hands you a live object, with properties you can filter and sort directly.'),
  ('mission-w14-03', 1, 'byte', 'The cleanup task runs on an interval. Every query you run needs to be precise the first time -- there might not be a second chance at this exact log.'),
  ('mission-w14-04', 1, 'luna', 'Defender didn''t fail to see this. Something told it to stop looking, in one specific folder, right before the real work started.'),
  ('mission-w14-05', 1, 'luna', 'Two separate questions again: who''s actually allowed to touch this evidence, and how do we reach forty other endpoints without waking up whatever''s wiping logs on this one.'),
  ('mission-w14-06', 1, 'luna', 'Put together the actual execution chain -- how this got onto the box in the first place, not just what it''s doing now.'),
  ('mission-w14-06', 2, 'byte', 'Chain confirmed. Same account as before -- svc_helpdesk -- same external address. This was never a new intrusion, just a new phase of the same one.'),
  ('mission-w14-06', 3, 'luna', 'And the cleanup tool itself?'),
  ('mission-w14-06', 4, 'byte', 'Running on a fifteen-minute cycle. We need to preserve what we have before the next run erases it.'),
  ('mission-w14-06', 5, 'luna', 'That hash isn''t new code. It''s a three-year-old project, reused byte-for-byte.'),
  ('mission-w14-06', 6, 'byte', 'SENTINEL. Officially retired. The same name Ava and I keep finding attached to hardware that shouldn''t still be active.'),
  ('mission-w14-06', 7, 'luna', 'There''s a line inside the script that isn''t written like a comment anyone leaves by accident: "verified -- reuse only, not new. If you''re reading this, you already know why."'),
  ('mission-w14-06', 8, 'byte', 'Whoever''s doing this isn''t hiding from us. They''re leaving a trail on purpose.'),
  ('mission-w14-06', 9, 'luna', 'We''ve got what we need from this machine, but we can''t keep doing this one artifact at a time. There are thousands of these across the network now, and no team reads that fast by hand.'),
  ('mission-w14-06', 10, 'byte', 'Time to stop analyzing one box at a time and start automating the analysis itself.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w14-01-o1', 'mission-w14-01', 1, 'Acknowledge the briefing', 'Confirm you''re ready to move quickly.'),
  ('mission-w14-02-o1', 'mission-w14-02', 1, 'Think in objects', 'Learn to filter and sort the object pipeline instead of parsing text.'),
  ('mission-w14-03-o1', 'mission-w14-03', 1, 'Hunt the log before it disappears', 'Query the event log precisely and identify the process destroying evidence.'),
  ('mission-w14-04-o1', 'mission-w14-04', 1, 'Correlate Defender and Sysmon', 'Show that Defender was deliberately blinded before the cleanup tool started operating.'),
  ('mission-w14-05-o1', 'mission-w14-05', 1, 'Check permissions and plan remote collection', 'Show the evidence folder''s permissions were tampered with, and choose a way to collect from many hosts safely.'),
  ('mission-w14-06-o1', 'mission-w14-06', 1, 'Reconstruct the execution chain', 'Order the events that show how the cleanup tool actually got onto this box.'),
  ('mission-w14-06-o2', 'mission-w14-06', 2, 'Trace the tooling''s origin', 'Find the findings that connect this cleanup tool to something beyond this single incident.'),
  ('mission-w14-06-o3', 'mission-w14-06', 3, 'Close the investigation', 'Submit the reconstructed execution chain and what it connects back to.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w14-01-o1-c1', 'mission-w14-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"luna","text":"Something is actively erasing evidence while we investigate. Ready to move quickly?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),

  ('mission-w14-02-o1-c1', 'mission-w14-02-o1', 1, 'multiple_choice', 'You need every process using more than 500MB of working set, sorted descending. Which pipeline does that?', '{"question":"You need every process using more than 500MB of working set, sorted descending. Which pipeline does that?","options":[{"id":"a","text":"tasklist | findstr \"500\""},{"id":"b","text":"Get-Process | Where-Object {$_.WorkingSet -gt 500MB} | Sort-Object WorkingSet -Descending"},{"id":"c","text":"Get-Process | Sort-Object Name"},{"id":"d","text":"Get-Process | Select-Object -First 500"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w14-02-o1-c2', 'mission-w14-02-o1', 2, 'drag_and_drop', 'Match each cmdlet to what its verb actually does.', '{"items":[{"id":"v1","text":"Get-Process"},{"id":"v2","text":"Stop-Process"},{"id":"v3","text":"New-Item"},{"id":"v4","text":"Set-ExecutionPolicy"}],"targets":[{"id":"retrieve","label":"Retrieve"},{"id":"terminate","label":"Terminate"},{"id":"create","label":"Create"},{"id":"configure","label":"Configure"}]}'::jsonb, '{"correctMapping":{"v1":"retrieve","v2":"terminate","v3":"create","v4":"configure"}}'::jsonb),

  ('mission-w14-03-o1-c1', 'mission-w14-03-o1', 1, 'multiple_choice', 'You need only Security log events with ID 4688 (process creation) from the last hour. Which command does that?', '{"question":"You need only Security log events with ID 4688 (process creation) from the last hour. Which command does that?","options":[{"id":"a","text":"Get-EventLog Security | findstr 4688"},{"id":"b","text":"Get-WinEvent -FilterHashtable @{LogName=''Security''; Id=4688; StartTime=(Get-Date).AddHours(-1)}"},{"id":"c","text":"Get-WinEvent -LogName Security | Select -First 4688"},{"id":"d","text":"Get-Content Security.log | grep 4688"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w14-03-o1-c2', 'mission-w14-03-o1', 2, 'investigation', 'Which event identifies the process actively destroying evidence?', '{"evidence":[{"id":"ev1","label":"Event 4688 (process creation)","detail":"powershell.exe launched \"Clear-PSReadLineHistory\" and began deleting log files, parent process CleanupSvc.exe, triggered by scheduled task MaintenanceSync"},{"id":"ev2","label":"Event 4688 (process creation)","detail":"Routine svchost.exe child process spawn, entirely expected"},{"id":"ev3","label":"Event 4688 (process creation)","detail":"explorer.exe launching a user-opened document, entirely expected"},{"id":"ev4","label":"Sysmon Event ID 1 (ProcessCreate)","detail":"Corroborates the same PowerShell process from ev1, but shows it running from C:\\ProgramData\\ instead of the standard PowerShell install path"}],"question":"Which events identify the process actively destroying evidence?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev4"]}'::jsonb),

  ('mission-w14-04-o1-c1', 'mission-w14-04-o1', 1, 'investigation', 'Which findings show Defender was deliberately blinded before the cleanup tool started operating?', '{"evidence":[{"id":"d1","label":"Get-MpPreference exclusion list","detail":"Shows exclusion path C:\\ProgramData\\SysCache\\ added two hours ago, absent from the baseline configuration"},{"id":"d2","label":"Get-MpThreatDetection history","detail":"No detections logged in the last six hours despite active suspicious activity elsewhere on the host"},{"id":"d3","label":"Sysmon Event ID 11 (FileCreate)","detail":"File created at C:\\ProgramData\\SysCache\\cleanup.ps1 immediately after the exclusion was added"},{"id":"d4","label":"Sysmon Event ID 1 (ProcessCreate)","detail":"cleanup.ps1 spawned repeatedly on a short interval, deleting files under C:\\Windows\\Temp and clearing PowerShell history"}],"question":"Which findings show Defender was deliberately blinded before the cleanup tool started operating?"}'::jsonb, '{"requiredEvidenceIds":["d1","d3"]}'::jsonb),
  ('mission-w14-04-o1-c2', 'mission-w14-04-o1', 2, 'multiple_choice', 'What''s the correct immediate response to this Defender exclusion?', '{"question":"What''s the correct immediate response to this Defender exclusion?","options":[{"id":"a","text":"Leave it -- exclusions are usually added for a good performance reason"},{"id":"b","text":"Remove the exclusion and trigger a full scan of that path immediately"},{"id":"c","text":"Just delete the folder without checking what''s in it"},{"id":"d","text":"Wait for the next scheduled scan cycle"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-w14-05-o1-c1', 'mission-w14-05-o1', 1, 'investigation', 'Which finding shows this folder''s permissions were deliberately loosened?', '{"evidence":[{"id":"a1","label":"Get-Acl on C:\\ProgramData\\SysCache","detail":"FullControl granted to NT AUTHORITY\\Authenticated Users -- far broader than the default admin-only inheritance"},{"id":"a2","label":"Get-Acl on C:\\Windows\\System32\\Tasks\\MaintenanceSync","detail":"Standard SYSTEM/Administrators-only permissions, unchanged"},{"id":"a3","label":"Baseline ACL policy document","detail":"Evidence and log folders should only be writable by SYSTEM and local Administrators"},{"id":"a4","label":"Local group membership audit","detail":"No new users have been added to Administrators recently"}],"question":"Which finding shows this folder''s permissions were deliberately loosened to let a low-privileged process tamper with evidence?"}'::jsonb, '{"requiredEvidenceIds":["a1","a3"]}'::jsonb),
  ('mission-w14-05-o1-c2', 'mission-w14-05-o1', 2, 'multiple_choice', 'You need to pull identical evidence from forty other endpoints without triggering the same cleanup tool. What''s the right approach?', '{"question":"You need to pull identical evidence from forty other endpoints without triggering the same cleanup tool. What''s the right approach?","options":[{"id":"a","text":"Log into each machine''s console individually with a domain admin account"},{"id":"b","text":"Use PowerShell remoting (Invoke-Command against a defined host list) with a scoped, low-noise credential and a read-only scriptblock"},{"id":"c","text":"Disable networking on all forty endpoints"},{"id":"d","text":"Email each site''s local IT staff and ask them to check manually"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-w14-06-o1-c1', 'mission-w14-06-o1', 1, 'interactive_diagram', 'Order these events as they actually occurred, earliest first.', '{"hotspots":[{"id":"logon","label":"Initial PowerShell launch under svc_helpdesk via RDP","explanation":"The chain begins with the same account and access method identified back in World 13."},{"id":"beacon","label":"Outbound connection to 203.0.113.77 for command retrieval","explanation":"The initial PowerShell session reaches out for further instructions."},{"id":"drop","label":"Child PowerShell process writes cleanup.ps1 to C:\\ProgramData\\SysCache","explanation":"A second process, spawned by the first, drops the cleanup tool to disk."},{"id":"task","label":"cleanup.ps1 registers itself as scheduled task MaintenanceSync","explanation":"The tool ensures it keeps running by scheduling itself."}],"task":"Order these events as they actually occurred, earliest first."}'::jsonb, '{"correctOrderIds":["logon","beacon","drop","task"]}'::jsonb),
  ('mission-w14-06-o2-c1', 'mission-w14-06-o2', 1, 'investigation', 'Which findings connect this cleanup tool to something beyond this single incident?', '{"evidence":[{"id":"s1","label":"cleanup.ps1 file hash (SHA-256)","detail":"Matches a hash referenced in an old internal wiki page documenting the retired SENTINEL project, exactly"},{"id":"s2","label":"SENTINEL wiki reference","detail":"\"Project SENTINEL, decommissioned three years ago -- internal tooling for authorized data collection, no longer in active use\""},{"id":"s3","label":"Comment inside cleanup.ps1","detail":"\"# verified -- reuse only, not new. If you''re reading this, you already know why.\""},{"id":"s4","label":"cleanup.ps1 file metadata","detail":"Compiled timestamp is recent, despite matching a three-year-old hash -- a byte-for-byte reuse of retired code, not a coincidence"}],"question":"Which findings connect this cleanup tool to something beyond this single incident?"}'::jsonb, '{"requiredEvidenceIds":["s1","s2"]}'::jsonb),
  ('mission-w14-06-o3-c1', 'mission-w14-06-o3', 1, 'boss_encounter', 'Submit the reconstructed execution chain and what it connects back to.', '{"stages":[{"objectiveRef":"mission-w14-06-o1","label":"The execution chain"},{"objectiveRef":"mission-w14-06-o2","label":"What it connects back to"}],"task":"Submit the reconstructed execution chain and what it connects back to."}'::jsonb, '{"requiredObjectiveIds":["mission-w14-06-o1","mission-w14-06-o2"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w14-01-o1-c1', 'orientation', 'There''s nothing to solve here -- just confirm you''re ready to continue.', 0, 1),

  ('mission-w14-02-o1-c1', 'orientation', 'Text-based tools like tasklist can''t easily filter or sort by a numeric property -- that''s the tell.', 10, 1),
  ('mission-w14-02-o1-c1', 'concept', 'Where-Object filters the object stream by a property''s actual value; Sort-Object -Descending orders it after filtering.', 20, 2),
  ('mission-w14-02-o1-c1', 'solution', 'Get-Process | Where-Object {$_.WorkingSet -gt 500MB} | Sort-Object WorkingSet -Descending filters by the real property value and sorts the result -- something text parsing can''t do reliably.', 30, 3),
  ('mission-w14-02-o1-c2', 'orientation', 'PowerShell cmdlet names follow a strict Verb-Noun pattern, and the verb tells you the intent.', 10, 1),
  ('mission-w14-02-o1-c2', 'concept', 'Get retrieves, Stop terminates, New creates, Set configures -- the verb is never decorative.', 20, 2),
  ('mission-w14-02-o1-c2', 'solution', 'Get-Process retrieves, Stop-Process terminates, New-Item creates, and Set-ExecutionPolicy configures -- matching each cmdlet to its verb''s actual meaning.', 30, 3),

  ('mission-w14-03-o1-c1', 'orientation', 'Get-EventLog and grep both work on text streams -- neither is built for precise, structured, high-volume querying.', 10, 1),
  ('mission-w14-03-o1-c1', 'concept', 'FilterHashtable lets Get-WinEvent filter at the source, by log name, event ID and time range, all at once.', 20, 2),
  ('mission-w14-03-o1-c1', 'solution', 'Get-WinEvent -FilterHashtable @{LogName=''Security''; Id=4688; StartTime=(Get-Date).AddHours(-1)} filters precisely by all three conditions at the source.', 30, 3),
  ('mission-w14-03-o1-c2', 'orientation', 'Two of these four events are completely ordinary process launches.', 15, 1),
  ('mission-w14-03-o1-c2', 'concept', 'Look for the process whose parent is a maintenance or cleanup service, and whose command line references clearing history.', 25, 2),
  ('mission-w14-03-o1-c2', 'tool_direction', 'Cross-reference the 4688 event''s command line against Sysmon''s record of that same process''s file path.', 35, 3),
  ('mission-w14-03-o1-c2', 'solution', 'Event 4688 showing powershell.exe running Clear-PSReadLineHistory under parent CleanupSvc.exe (ev1), corroborated by Sysmon showing that same process running from C:\ProgramData\ instead of a standard install path (ev4), together identify the process actively destroying evidence.', 45, 4),

  ('mission-w14-04-o1-c1', 'orientation', 'One exclusion and one file event, moments apart, tell the real story here.', 15, 1),
  ('mission-w14-04-o1-c1', 'concept', 'An exclusion path that doesn''t match the baseline configuration is worth treating as a deliberate decision, not a coincidence.', 25, 2),
  ('mission-w14-04-o1-c1', 'tool_direction', 'Compare the exclusion''s timestamp against the timestamp of the first file created inside it.', 35, 3),
  ('mission-w14-04-o1-c1', 'solution', 'The unapproved exclusion for C:\ProgramData\SysCache\ (d1), followed moments later by a file created inside that exact excluded path (d3), shows Defender was deliberately blinded right before the cleanup tool started operating. The lack of detections (d2) is a downstream symptom, and the repeated spawning (d4) is what happened next, not the identifying evidence.', 45, 4),
  ('mission-w14-04-o1-c2', 'orientation', 'An exclusion nobody approved should never just be left in place.', 10, 1),
  ('mission-w14-04-o1-c2', 'solution', 'Remove the exclusion and immediately scan that path -- waiting or deleting blindly both risk losing evidence or missing what else is hiding there.', 20, 2),

  ('mission-w14-05-o1-c1', 'orientation', 'One of these four items directly contradicts a documented policy.', 15, 1),
  ('mission-w14-05-o1-c1', 'concept', 'Compare the actual permissions on the evidence folder against what the baseline policy says they should be.', 25, 2),
  ('mission-w14-05-o1-c1', 'tool_direction', 'Check who holds FullControl on C:\ProgramData\SysCache against the policy document''s stated default.', 35, 3),
  ('mission-w14-05-o1-c1', 'solution', 'Get-Acl showing Authenticated Users with FullControl on the evidence folder (a1), compared against the baseline policy stating only SYSTEM and Administrators should have write access (a3), shows this folder''s permissions were deliberately loosened. The scheduled task''s own permissions are untouched (a2), and no new admin accounts were added (a4) -- the tampering happened at the folder level.', 45, 4),
  ('mission-w14-05-o1-c2', 'orientation', 'Individually logging into forty machines doesn''t scale, and it leaves forty separate footprints.', 10, 1),
  ('mission-w14-05-o1-c2', 'concept', 'PowerShell remoting lets you run the same scoped, read-only script against many hosts from one place, under one controlled credential.', 20, 2),
  ('mission-w14-05-o1-c2', 'solution', 'Invoke-Command against a defined host list, using a scoped low-noise credential and a read-only scriptblock, gets identical evidence from every endpoint without multiplying the footprint or needing individual console access.', 30, 3),

  ('mission-w14-06-o1-c1', 'orientation', 'The earliest event in this chain isn''t the one you found first -- it''s the one that made everything else possible.', 20, 1),
  ('mission-w14-06-o1-c1', 'concept', 'Work forward from how the attacker actually got a shell running, not backward from what''s currently annoying you.', 30, 2),
  ('mission-w14-06-o1-c1', 'tool_direction', 'Order by timestamp: the logon event, then the network connection, then the file write, then the task registration.', 40, 3),
  ('mission-w14-06-o1-c1', 'near_solution', 'Everything traces back to one RDP session under an account you''ve seen before.', 50, 4),
  ('mission-w14-06-o1-c1', 'solution', 'The real order is: the RDP logon under svc_helpdesk starts the chain, followed by the outbound connection for command retrieval, then the child process writing cleanup.ps1 to disk, and finally the scheduled task registering itself to keep the cleanup running. Each step depends on the one before it.', 65, 5),

  ('mission-w14-06-o2-c1', 'orientation', 'One of these four items is a hash. One is a definition. The other two are context and misdirection.', 20, 1),
  ('mission-w14-06-o2-c1', 'concept', 'A file that matches a three-year-old hash exactly isn''t new code that happens to look similar -- it''s the same code.', 30, 2),
  ('mission-w14-06-o2-c1', 'tool_direction', 'Compare cleanup.ps1''s hash against internal documentation for retired projects, not against known-malware signatures.', 40, 3),
  ('mission-w14-06-o2-c1', 'near_solution', 'The hash match points to a specific, named, officially decommissioned internal project -- not a generic attacker tool.', 50, 4),
  ('mission-w14-06-o2-c1', 'solution', 'cleanup.ps1''s hash (s1) matches internal documentation for the retired SENTINEL project (s2) exactly -- this is reused SENTINEL code, not new malware. The comment inside the script (s3) and its recent compile timestamp (s4) are corroborating detail, not the core identifying link.', 65, 5),

  ('mission-w14-06-o3-c1', 'orientation', 'You already have both pieces -- the sequence of events and what they trace back to.', 20, 1),
  ('mission-w14-06-o3-c1', 'concept', 'State the chain in the order it actually happened, then name what the tooling connects to.', 30, 2),
  ('mission-w14-06-o3-c1', 'tool_direction', 'Logon, then connection, then drop, then task -- and then the retired project the drop-file hash matches.', 40, 3),
  ('mission-w14-06-o3-c1', 'near_solution', 'RDP logon under svc_helpdesk, outbound connection, cleanup.ps1 dropped, task registered -- hash matches SENTINEL.', 50, 4),
  ('mission-w14-06-o3-c1', 'solution', 'The execution chain is: RDP logon under svc_helpdesk, an outbound connection for command retrieval, a child process writing cleanup.ps1 to disk, and that script registering itself as a recurring scheduled task. Its file hash matches the retired SENTINEL project''s documentation exactly -- this incident is reusing years-old internal tooling, not building something new.', 65, 5);
